<template>
    <div class="holiday-setting" @click.stop>
        <div class="label-container">
            <div class="label">
                <div class="color-block red"></div>
                <div class="title">节假日</div>
            </div>
            <div class="label">
                <div class="color-block grey"></div>
                <div class="title">工作日</div>
            </div>
        </div>
        <header class="toolbar">
            <div class="year-operate operate">
                <div title="上一年" class="button left" @click="handlePreYear">
                    <timeLeftImg :color="'#fff'"/>
                </div>
                <span class="time">{{year + '年'}}</span>
                <div title="下一年" class="button right" @click="handleNextYear">
                    <timeRightImg :color="'#fff'"/>
                </div>
            </div>
            <div class="month-operate operate">
                <div title="上一月" class="button left" @click="handlePreMonth">
                    <timeLeftImg :color="'#fff'"/>
                </div>
                <span class="time">{{formatterNumber(month) + '月'}}</span>
                <div title="下一月" class="button right" @click="handleNextMonth">
                    <timeRightImg :color="'#fff'"/>
                </div>
            </div>
        </header>
        <section class="date-wrapper">
            <div class="date-title">
                <div v-for="(item, index) in weeks" :key="index" class="week-item" :class="{holiday: item.holiday}">{{item.week}}</div>
            </div>
            <div class="date-content">
                <div class="date-row" v-for="(weekTimes, index) in createTimes" :key="index">
                    <div
                        class="date-item"
                        v-for="time in weekTimes"
                        :key="time.key"
                        :class="[{'not-current-month' : !time.isCurrentMonth}, {'holiday' : time.isHoliday}]"
                        @click="handledateClick(time)"
                    >
                        <div class="time">{{time.day}}</div>
                        <div class="time-info" :class="time.infoStatus">
                            {{time.info}}
                        </div>
                    </div>
                </div>
            </div>
        </section>
    </div>
</template>

<script>
import Gikam from "../../../../core/gikam-core";
import Mask from "../../../template/mask/mask";
import Vue from "vue";

export default {
    props: {
        options: Object
    },

    created() {
        this.initCompoent();
    },

    data() {
        return {
            weeks: [
                {week: '星期日', holiday: true},
                {week: '星期一', holiday: false},
                {week: '星期二', holiday: false},
                {week: '星期三', holiday: false},
                {week: '星期四', holiday: false},
                {week: '星期五', holiday: false},
                {week: '星期六', holiday: true}
            ],
            baseUrl: void 0,
            publicHolidays: void 0,
            year: void 0,
            month: void 0,
            //休假-集合
            holidaysObj: {},
            holidayArray: void 0,
            lunarInfo: void 0
        };
    },

    computed: {
        //计算展示时间数据
        createTimes() {
            //获取起始时间对象
            let startDate = new Date(this.year, this.month - 1, 1);
            //获取起始日期，所属周几
            let startDay = startDate.getDay();
            //获取结束时间对象
            let endDate = new Date(this.year, this.month, 0);
            //获取结束日期，所属周几
            let endDay = endDate.getDay();

            //计算起始日期
            startDate.setDate(startDate.getDate() - startDay);
            //计算结束日期
            endDate.setDate(endDate.getDate() + (7 - endDay));

            //计算日期差
            let totalDays =
                (endDate.getTime() - startDate.getTime()) /
                (24 * 60 * 60 * 1000);

            //获取当前日期时间（格式化）
            let nowDate = Gikam.DateUtils.formatter(new Date(), "yyyyMMdd");

            const timeArray = [];
            let lunarObj = null;
            for (let i = 0, j = 0; i < totalDays; i++) {
                if (i % 7 === 0) {
                    if (i !== 0) j++;
                    timeArray[j] = [];
                }

                let timeValueFmt = Gikam.DateUtils.formatter(
                    startDate,
                    "yyyy-MM-dd"
                );

                let timeValue = timeValueFmt.replace(/-/g, "");

                const time = {};
                time.key = timeValue;
                //获取当前日期
                time.day = this.formatterNumber(startDate.getDate());
                time.dateFmt = timeValueFmt;
                //获取当前格式化时间
                time.value = timeValue;
                //判断是否当前月
                time.isCurrentMonth =
                    Gikam.DateUtils.formatter(startDate, "yyyy-MM") ===
                    this.year + "-" + this.formatterNumber(this.month);
                //判断是否周末
                let isWeekend =
                    startDate.getDay() === 0 || startDate.getDay() === 6;
                //判断是否存在WorkDay,如果存在以参数为准，如不存在判断是否为周末
                time.isHoliday = this.holidaysObj.hasOwnProperty(timeValue)
                    ? !this.holidaysObj[timeValue].isWorkDay
                    : isWeekend;
                //当前日期为节假日时，展示假期名称
                let holidayName = this.holidaysObj.hasOwnProperty(timeValue)
                    ? this.holidaysObj[timeValue].name
                    : "";
                if (holidayName) {
                    time.info = holidayName;
                    //记录日期提示状态
                    time.infoStatus = 'holiday';
                    lunarObj.day++;
                //当前日期为今天时，展示今天
                } else if (timeValue === nowDate) {
                    time.info = '今天';
                    time.infoStatus = 'today';
                    lunarObj.day++;
                //当前日期为普通日期时，展示阴历日期
                } else {
                    let tempTimeArray = timeValueFmt.split('-');
                    if (!lunarObj || lunarObj.day > 28) {
                        lunarObj = this.solar2lunar(parseInt(tempTimeArray[0]), parseInt(tempTimeArray[1]), parseInt(tempTimeArray[2]));
                    } else {
                        lunarObj.day++;
                    }
                    let lunarStr = this.dateConversion(lunarObj);
                    time.info = lunarStr;
                    time.isHoliday ? time.infoStatus = 'holiday' : time.infoStatus = 'default';
                }

                timeArray[j].push(time);
                startDate.setDate(startDate.getDate() + 1);
            }
            return timeArray;
        }
    },

    watch: {
        //将请求到的假期数组转换为对象
        holidayArray(newValue) {
            const holidaysObj = Gikam.deepExtend(this.publicHolidays);
            //如果假期数据不存在或不为数组则返回空数组
            if (newValue && newValue instanceof Array) {
                newValue.forEach(element => {
                    if (holidaysObj.hasOwnProperty(element.ymd)) {
                        holidaysObj[element.ymd].time = element.ymd;
                        holidaysObj[element.ymd].isWorkDay =
                            element.isWorkDay == 1;
                    } else {
                        holidaysObj[element.ymd] = {
                            time: element.ymd,
                            isWorkDay: element.isWorkDay == 1,
                            name: ""
                        };
                    }
                });
            }
            return (this.holidaysObj = holidaysObj);
        }
    },

    methods: {
        handledateClick(time) {
            if (!time.isCurrentMonth) return;
            if (!this.baseUrl) return;

            let isWorkDay = time.isHoliday;
            let ymd = time.value;
            let holidayName = time.holidayName;
            
            this.openMask();

            let _this = this;
            let tempDateArray = time.dateFmt.split("-");
            let updateUrl =
                this.baseUrl +
                `/${tempDateArray[0]}/${tempDateArray[1]}/${tempDateArray[2]}/${
                    isWorkDay ? "1" : 0
                }`;
            Gikam.postText(updateUrl, {})
                .done(() => {
                    _this.$set(_this.holidaysObj, ymd, {
                        time: ymd,
                        isWorkDay: isWorkDay,
                        name: holidayName
                    });
                })
                .always(() => {
                    this.closeMask();
                });
        },

        refreshYear() {
            this.getPublicHolidays();
            this.getMonthHoliday();
        },

        handlePreYear() {
            this.year--;
            this.refreshYear();
        },

        handleNextYear() {
            this.year++;
            this.refreshYear();
        },

        handlePreMonth() {
            if (parseInt(this.month) - 1 < 1) {
                this.month = 12;
                this.year--;
                this.refreshYear();
                return;
            } else {
                this.month--;
            }
            this.getMonthHoliday();
        },

        handleNextMonth() {
            if (parseInt(this.month) + 1 > 12) {
                this.month = 1;
                this.year++;
                this.refreshYear();
                return;
            } else {
                this.month++;
            }
            this.getMonthHoliday();
        },

        //获取当前月假期数据
        getMonthHoliday() {
            if (!this.baseUrl) {
                this.holidayArray = [];
                return;
            }
            let queryUrl = this.baseUrl + `/${this.year}/${this.month}`;
            let _this = this;
            Gikam.getJson(queryUrl)
                .done(function(holidayArray) {
                    _this.holidayArray = holidayArray;
                })
                .fail(function() {
                    _this.holidayArray = [];
                });
        },

        //获取全年公休假日数据
        getPublicHolidays() {
            let defaultPublicHolidays = [
                { type: "y", time: "10-01", name: "国庆节", isWorkDay: false },
                { type: "y", time: "05-01", name: "劳动节", isWorkDay: false },
                { type: "y", time: "01-01", name: "元旦", isWorkDay: false },
                { type: "y", time: "04-04", name: "清明节", isWorkDay: false },
                { type: "l", time: "12-30", name: "除夕节", isWorkDay: false },
                { type: "l", time: "01-01", name: "春节", isWorkDay: false },
                { type: "l", time: "05-05", name: "端午节", isWorkDay: false },
                { type: "l", time: "08-15", name: "中秋节", isWorkDay: false }
            ];

            const publicHolidays = {};

            for (
                let i = 0, length = defaultPublicHolidays.length;
                i < length;
                i++
            ) {
                let timeStr = "";
                //获取默认假期配置参数
                let tempHoliday = defaultPublicHolidays[i];
                //判断假期是否为阳历日期
                if (tempHoliday.type === "y") {
                    timeStr = this.year + tempHoliday.time.replace(/-/g, "");
                    publicHolidays[timeStr] = {
                        time: timeStr,
                        isWorkDay: tempHoliday.isWorkDay,
                        name: tempHoliday.name
                    };
                } else {
                    let holidayYear = this.year;
                    //判断是否为除夕，如为除夕当前年 - 1
                    if (tempHoliday.name.indexOf("除夕") != -1)
                        holidayYear -= 1;
                    let monthYear = tempHoliday.time.split("-");
                    //依据阴历日期计算阳历日期
                    let ytime = this.lunar2solar(
                        holidayYear,
                        parseInt(monthYear[0]),
                        parseInt(monthYear[1])
                    );
                    //日期超出限制跳出此次循环
                    if (ytime === -1) continue;
                    timeStr =
                        ytime.year.toString() +
                        this.formatterNumber(ytime.month).toString() +
                        this.formatterNumber(ytime.day).toString();
                    publicHolidays[timeStr] = {
                        time: timeStr,
                        isWorkDay: tempHoliday.isWorkDay,
                        name: tempHoliday.name
                    };
                }
            }
            this.publicHolidays = publicHolidays;
        },

        //初始化组件
        initCompoent() {
            this.baseUrl = this.options.baseUrl;
            this.initLunarInfo();
            let nowDate = new Date();
            this.year = Gikam.DateUtils.formatter(nowDate, "yyyy");
            this.month = Gikam.DateUtils.formatter(nowDate, "MM");
            this.getPublicHolidays();
            this.getMonthHoliday();
        },

        //传入参数为单位数时,在数字前添加0
        formatterNumber(number) {
            if (isNaN(number)) return;
            let tempNumber = parseInt(number);
            if (tempNumber < 10) {
                tempNumber = "0" + tempNumber;
            }
            return tempNumber;
        },

        //阴历日期数字转中文
        dateConversion(lunarObj) {
            let month = lunarObj.month;
            let day = lunarObj.day;

            let units = [ '十', '一', '二', '三', '四', '五', '六', '七', '八', '九', '十', '十一', '十二'];
            let tens = ['初', '十',  '廿', '三'];
            let tensNumber = parseInt(day/10);
            let unitsNumber = day%10;
            
            //排除每月十号显示十十的情况
            if (tensNumber === 1 && unitsNumber === 0) tensNumber = 0;

            let lunarStr = tens[tensNumber] + units[unitsNumber];
            if (unitsNumber == 1 && tensNumber == 0) lunarStr = `${units[month]}月`;
            return lunarStr;
        },

        //传入阳历年月日以及传入的月份是否闰月获得农历时间 <=>JSON
        //参数区间1900.1.31~2049.12.1
        solar2lunar(y, m, d) { 
            //年份限定、上限
            if(y < 1900 || y > 2049) {
                return -1;// undefined转换为数字变为NaN
            }
            //公历传参最下限
            if(y == 1900 && m == 1 && d < 31) {
                return -1;
            }
            //未传参  获得当天
            let objDate = void 0;
            if(!y) {
                objDate = new Date();
            } else {
                objDate = new Date(y, parseInt(m) - 1, d)
            }
            let i, temp = 0;

            let offset = (Date.UTC(objDate.getFullYear(), objDate.getMonth(), objDate.getDate()) - Date.UTC(1900,0,31)) / 86400000;

            for(i = 1900; i < 2050 && offset > 0; i++) {
                temp = this.lYearDays(i);
                offset -= temp;
            }
            if(offset < 0) {
                offset += temp; i--;
            }

            //农历年
            let year = i;
            //闰哪个月
            let leap = this.leapMonth(i); 
            let isLeap = false;

            //效验闰月
            for(i = 1; i < 13 && offset > 0; i++) {
                //闰月
                if(leap > 0 && i == (leap + 1) && isLeap == false){
                    --i;
                    //计算农历闰月天数
                    isLeap = true; temp = this.leapDays(year); 
                }
                else{
                    //计算农历普通月天数
                    temp = this.monthDays(year, i);
                }
                //解除闰月
                if(isLeap == true && i == (leap+1)) { isLeap = false; }
                offset -= temp;
            }
            // 闰月导致数组下标重叠取反
            if(offset == 0 && leap > 0 && i == leap + 1)
            {
                if(isLeap){
                    isLeap = false;
                }else{
                    isLeap = true; --i;
                }
            }
            if (offset < 0) {
                offset += temp; --i;
            }
            //农历月
            let month = i;
            //农历日
            let day = offset + 1;


            return {'year':year,'month':month,'day':day};
        },

        //传入农历年月日以及传入的月份是否闰月获得阳历时间 <=>JSON
        //参数区间1900.1.31~2049.12.1
        lunar2solar(y, m, d) {
            let isLeapMonth = false;
            let leapMonth = this.leapMonth(y);

            //计算是否为闰月
            if (leapMonth == m) isLeapMonth = true;

            //超出了最大极限值
            if (
                (y == 2049 && m == 12 && d > 1) ||
                (y == 1900 && m == 1 && d < 31)
            )
                return -1;
            let day = this.monthDays(y, m);
            let _day = day;

            //如果为闰月，则使用_day使用leapDays函数
            if (isLeapMonth) {
                _day = this.leapDays(y, m);
            }

            //参数合法性效验
            if (y < 1900 || y > 2049) {
                return -1;
            }
            if (d > _day) d = _day;

            //计算农历的时间差
            let offset = 0;
            for (let i = 1900; i < y; i++) {
                offset += this.lYearDays(i);
            }
            let leap = 0,
                isAdd = false;
            for (let i = 1; i < m; i++) {
                leap = this.leapMonth(y);
                //处理闰月
                if (!isAdd) {
                    if (leap <= i && leap > 0) {
                        offset += this.leapDays(y);
                        isAdd = true;
                    }
                }
                offset += this.monthDays(y, i);
            }
            //转换闰月农历 需补充该年闰月的前一个月的时差
            if (isLeapMonth) {
                offset += day;
            }
            //1900年农历正月一日的公历时间为1900年1月30日0时0分0秒(该时间也是本农历的最开始起始点)
            let stmap = Date.UTC(1900, 1, 30, 0, 0, 0);
            let calObj = new Date((offset + d - 31) * 86400000 + stmap);
            let cY = calObj.getUTCFullYear();
            let cM = calObj.getUTCMonth() + 1;
            let cD = calObj.getUTCDate();

            return { year: cY, month: cM, day: cD };
        },

        //返回农历y年一整年的总天数
        lYearDays(y) {
            let i,
                sum = 348;
            for (i = 0x8000; i > 0x8; i >>= 1) {
                sum += this.lunarInfo[y - 1900] & i ? 1 : 0;
            }
            return sum + this.leapDays(y);
        },

        //返回农历y年闰月是哪个月；若y年没有闰月 则返回0
        //闰字编码 \u95f0
        leapMonth(y) {
            return this.lunarInfo[y - 1900] & 0xf;
        },

        //返回农历y年闰月的天数 若该年没有闰月则返回0
        leapDays(y) {
            if (this.leapMonth(y)) {
                return this.lunarInfo[y - 1900] & 0x10000 ? 30 : 29;
            }
            return 0;
        },

        //返回农历y年m月（非闰月）的总天数，计算m为闰月时的天数请使用leapDays方法
        monthDays(y, m) {
            if (m > 12 || m < 1) {
                return -1;
            } //月份参数从1至12，参数错误返回-1
            return this.lunarInfo[y - 1900] & (0x10000 >> m) ? 30 : 29;
        },

        initLunarInfo() {
            this.lunarInfo = [
                0x04bd8,
                0x04ae0,
                0x0a570,
                0x054d5,
                0x0d260,
                0x0d950,
                0x16554,
                0x056a0,
                0x09ad0,
                0x055d2, //1900-1909
                0x04ae0,
                0x0a5b6,
                0x0a4d0,
                0x0d250,
                0x1d255,
                0x0b540,
                0x0d6a0,
                0x0ada2,
                0x095b0,
                0x14977, //1910-1919
                0x04970,
                0x0a4b0,
                0x0b4b5,
                0x06a50,
                0x06d40,
                0x1ab54,
                0x02b60,
                0x09570,
                0x052f2,
                0x04970, //1920-1929
                0x06566,
                0x0d4a0,
                0x0ea50,
                0x06e95,
                0x05ad0,
                0x02b60,
                0x186e3,
                0x092e0,
                0x1c8d7,
                0x0c950, //1930-1939
                0x0d4a0,
                0x1d8a6,
                0x0b550,
                0x056a0,
                0x1a5b4,
                0x025d0,
                0x092d0,
                0x0d2b2,
                0x0a950,
                0x0b557, //1940-1949
                0x06ca0,
                0x0b550,
                0x15355,
                0x04da0,
                0x0a5b0,
                0x14573,
                0x052b0,
                0x0a9a8,
                0x0e950,
                0x06aa0, //1950-1959
                0x0aea6,
                0x0ab50,
                0x04b60,
                0x0aae4,
                0x0a570,
                0x05260,
                0x0f263,
                0x0d950,
                0x05b57,
                0x056a0, //1960-1969
                0x096d0,
                0x04dd5,
                0x04ad0,
                0x0a4d0,
                0x0d4d4,
                0x0d250,
                0x0d558,
                0x0b540,
                0x0b6a0,
                0x195a6, //1970-1979
                0x095b0,
                0x049b0,
                0x0a974,
                0x0a4b0,
                0x0b27a,
                0x06a50,
                0x06d40,
                0x0af46,
                0x0ab60,
                0x09570, //1980-1989
                0x04af5,
                0x04970,
                0x064b0,
                0x074a3,
                0x0ea50,
                0x06b58,
                0x05ac0,
                0x0ab60,
                0x096d5,
                0x092e0, //1990-1999
                0x0c960,
                0x0d954,
                0x0d4a0,
                0x0da50,
                0x07552,
                0x056a0,
                0x0abb7,
                0x025d0,
                0x092d0,
                0x0cab5, //2000-2009
                0x0a950,
                0x0b4a0,
                0x0baa4,
                0x0ad50,
                0x055d9,
                0x04ba0,
                0x0a5b0,
                0x15176,
                0x052b0,
                0x0a930, //2010-2019
                0x07954,
                0x06aa0,
                0x0ad50,
                0x05b52,
                0x04b60,
                0x0a6e6,
                0x0a4e0,
                0x0d260,
                0x0ea65,
                0x0d530, //2020-2029
                0x05aa0,
                0x076a3,
                0x096d0,
                0x04afb,
                0x04ad0,
                0x0a4d0,
                0x1d0b6,
                0x0d250,
                0x0d520,
                0x0dd45, //2030-2039
                0x0b5a0,
                0x056d0,
                0x055b2,
                0x049b0,
                0x0a577,
                0x0a4b0,
                0x0aa50,
                0x1b255,
                0x06d20,
                0x0ada0 //2040-2049
            ];
        },

        //打开遮罩
        openMask() {
            if (this.maskModel) {
                return;
            }
            this.maskModel = new Vue({
                el: Gikam.createDom("div", document.body),
                components: { Mask },
                render() {
                    return <Mask />;
                }
            });
        },

        //关闭遮罩
        closeMask() {
            this.maskModel.$nextTick(() => {
                this.maskModel.$destroy();
                Gikam.removeDom(this.maskModel.$el);
                this.maskModel = null;
            });
        }
    }
};
</script>

<style scoped>
.holiday-setting {
    font-size: 14px;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.label-container {
    width: 976px;
    display: flex;
    margin: 6px auto 0;
}

.label-container .label {
    display: flex;
    align-items: center;
}

.label-container .label:not(:first-child) {
